def compute_change_pct(latest, prior):
    if latest is None or prior is None:
        return None
    if prior == 0:
        return None
    return round(((latest - prior) / prior) * 100.0, 2)

def classify_regime(series_type, quote_base_is_foreign, change_30d_pct):
    if change_30d_pct is None:
        return 'UNKNOWN'
    if series_type == 'fx_major' or series_type == 'fx_em':
        # If the series quote is USD-as-base (higher value = USD stronger), rising series = USD_STRENGTH.
        # If the series quote is foreign-as-base (higher value = foreign stronger), rising series = USD_WEAKNESS.
        if quote_base_is_foreign:
            if change_30d_pct >= 2.0:
                return 'USD_WEAKNESS'
            if change_30d_pct <= -2.0:
                return 'USD_STRENGTH'
            return 'STABLE'
        if change_30d_pct >= 2.0:
            return 'USD_STRENGTH'
        if change_30d_pct <= -2.0:
            return 'USD_WEAKNESS'
        return 'STABLE'
    if series_type == 'real_yield':
        if change_30d_pct >= 10.0:
            return 'RISING'
        if change_30d_pct <= -10.0:
            return 'FALLING'
        return 'STABLE'
    if series_type == 'breakeven':
        if change_30d_pct >= 5.0:
            return 'INFLATION_RISING'
        if change_30d_pct <= -5.0:
            return 'INFLATION_FALLING'
        return 'ANCHORED'
    return 'UNKNOWN'

def thesis_for(series_type, regime, pair, etf):
    if series_type == 'fx_major' or series_type == 'fx_em':
        if regime == 'USD_STRENGTH':
            return 'USD bid ' + pair + ' - short ' + etf + ', emerging-market drag (EM equities pressured)'
        if regime == 'USD_WEAKNESS':
            return 'USD soft ' + pair + ' - long ' + etf + ', tailwind for EM equities + commodities'
        return 'FX range-bound - carry-trade opportunity if rate differential widens'
    if series_type == 'real_yield':
        if regime == 'RISING':
            return 'Real yields rising - tight financial conditions; long USD, short gold (GLD), short long-duration equities (ARKK)'
        if regime == 'FALLING':
            return 'Real yields falling - easier conditions; long TIP, long gold (GLD), long growth'
        return 'Real yields stable - no FX/gold regime shift signalled'
    if series_type == 'breakeven':
        if regime == 'INFLATION_RISING':
            return 'Inflation expectations rising - long RINF, commodities (DBC), short long-duration bonds'
        if regime == 'INFLATION_FALLING':
            return 'Inflation expectations falling - long duration (TLT), short commodities'
        return 'Inflation anchored - no regime shift'
    return 'Monitor for regime changes'

