    values = []
    for oi in range(len(obs)):
        o = obs[oi]
        if not isinstance(o, dict):
            continue
        v = o.get('value', '.')
        if v == '.' or v is None:
            continue
        try:
            fv = float(v)
        except Exception:
            continue
        values.append({'date': str(o.get('date', '') or ''), 'value': fv})
